CREATE OR REPLACE FUNCTION public.debitar_carteira(p_tenant uuid, p_client uuid, p_valor bigint, p_reason text, p_source uuid DEFAULT NULL::uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_saldo bigint;
begin
  if p_valor <= 0 then
    raise exception 'valor de débito precisa ser positivo' using errcode = '22023';
  end if;

  perform 1 from public.clients
   where id = p_client and tenant_id = p_tenant
     for update;

  if not found then
    raise exception 'cliente não encontrada neste estabelecimento' using errcode = 'P0002';
  end if;

  select coalesce(sum(amount_cents), 0) into v_saldo
    from public.wallet_entries
   where tenant_id = p_tenant and client_id = p_client;

  if v_saldo < p_valor then
    raise exception 'saldo insuficiente' using errcode = '53000';
  end if;

  insert into public.wallet_entries (tenant_id, client_id, amount_cents, reason, source_id)
  values (p_tenant, p_client, -p_valor, p_reason, p_source);

  return v_saldo - p_valor;
end;
$function$

CREATE OR REPLACE FUNCTION public.redigir_trilha_do_cliente(p_tenant uuid, p_client uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  n_trilha bigint;
  n_chaves bigint;
  agulha   text;
begin
  if not exists (
    select 1 from public.clients
     where id = p_client and tenant_id = p_tenant and anonymized_at is not null
  ) then
    raise exception 'a trilha so e redigida depois da eliminacao da cliente';
  end if;

  agulha := '%' || p_client::text || '%';

  update public.audit_log
     set before = null,
         after  = null
   where tenant_id = p_tenant
     and (before is not null or after is not null)
     and (
       (entity = 'clients' and entity_id = p_client)
       or before::text like agulha
       or after::text  like agulha
     );
  get diagnostics n_trilha = row_count;

  update public.idempotency_keys
     set response_body = jsonb_build_object('eliminado', true)
   where tenant_id = p_tenant
     and response_body is not null
     and response_body::text like agulha;
  get diagnostics n_chaves = row_count;

  return jsonb_build_object('audit_log', n_trilha, 'idempotency_keys', n_chaves);
end
$function$
